.form-fields {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: .3rem 1.2rem;
  font-family: var(--sans); font-size: .72rem; color: var(--ink-soft); margin: .6rem 0 1rem;
}
.form-fields div { border-bottom: 1px solid var(--ink-faint); padding-top: 1.35rem; }
.box {
  display: inline-block; width: .75rem; height: .75rem; margin-right: .2rem;
  border: 1px solid var(--ink-soft); border-radius: 2px; vertical-align: -.1rem;
}
.form-sheet td.tick { width: 2.6rem; text-align: center; }
.form-sheet td.write { width: 34%; }
.write-line { border-bottom: 1px solid var(--ink-faint); height: 1.5rem; max-width: none; }
.page-break { break-before: page; }

@page form { margin: .4in .45in; }

@media print {
  body.form-sheet { page: form; font-size: 8.8pt; line-height: 1.3; }
  .form-sheet .form-fields div { padding-top: 1.05rem; }
  .form-sheet h1 { font-size: 1.35rem; }
  .form-sheet h2 { font-size: .95rem; margin: .7rem 0 .25rem; }
  .form-sheet .eyebrow { margin-bottom: .2rem; }
  .form-sheet .subtitle { font-size: .85rem; margin-bottom: .4rem; }
  .form-sheet p, .form-sheet ul, .form-sheet ol { margin-bottom: .4rem; max-width: none; }
  .form-sheet li { margin-bottom: .15rem; }
  .form-sheet table { margin: .3rem 0 .4rem; font-size: 7.6pt; }
  .form-sheet th, .form-sheet td { padding: .16rem .4rem; }
  .form-sheet .callout { padding: .45rem .7rem; margin: .5rem 0; max-width: none; }
  .form-sheet .cite { margin: .35rem 0; font-size: 7pt; max-width: none; }
  .form-sheet a[href^="http"]::after { content: none; }
}

/* Locked quiz options keep full ink so the correct answer does not grey out. */
.quiz__opt:disabled { color: var(--ink); opacity: 1; cursor: default; }

